    def fetch_closed_orders(self, symbol: Str = None, since: Int = None, limit: Int = None, params={}) -> List[Order]:
        """
        fetches information on multiple closed orders made by the user

        https://docs.nado.xyz/developer-resources/api/archive-indexer/orders
        https://docs.nado.xyz/developer-resources/api/trigger/queries/list-trigger-orders

        :param str [symbol]: unified market symbol of the market orders were made in
        :param int [since]: timestamp in ms of the earliest order
        :param int [limit]: the maximum number of orders structures to retrieve
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.subaccount]: the 12-byte subaccount identifier, defaults to 'default'
        :param int [params.until]: timestamp in ms of the latest order to fetch
        :param boolean [params.trigger]: whether the order is a trigger order
        :returns Order[]: a list of `order structures <https://docs.ccxt.com/#/?id=order-structure>`
        """
        if self.walletAddress is None:
            raise ArgumentsRequired(self.id + ' fetchClosedOrders() requires walletAddress')
        self.load_markets()
        market = None
        if symbol is not None:
            market = self.market(symbol)
        subaccount = None
        subaccount, params = self.handle_option_and_params(params, 'fetchClosedOrders', 'subaccount', 'default')
        sender = self.create_subaccount(self.walletAddress, subaccount)
        trigger = self.safe_bool_2(params, 'stop', 'trigger')
        if trigger:
            return self.fetch_orders(symbol, since, None, self.extend(params, {
                'status_types': [
                    'triggered', 'triggering', 'twap_executing', 'twap_completed',
                ],
            }))
        ordersRequest = {
            'subaccounts': [
                sender,
            ],
        }
        if market is not None:
            ordersRequest['product_ids'] = [self.parse_to_int(market['id'])]
        ordersRequest, params = self.handle_until_option('max_time', ordersRequest, params, 0.001)
        if limit is not None:
            ordersRequest['limit'] = min(limit, 500)
        request = {
            'orders': ordersRequest,
        }
        response = self.archivePost(self.deep_extend(request, params))
        #
        #     {
        #         "orders": [
        #             {
        #                 "digest": "0xf4f7a8767faf0c7f72251a1f9e5da590f708fd9842bf8fcdeacbaa0237958fff",
        #                 "subaccount": "0x12a0b4888021576eb10a67616dd3dd3d9ce206b664656661756c740000000000",
        #                 "product_id": 1,
        #                 "submission_idx": "563024",
        #                 "amount": "20000000000000000000",
        #                 "price_x18": "1751900000000000000000",
        #                 "base_filled": "20000000000000000000",
        #                 "quote_filled": "-35038000000000000000000",
        #                 "fee": "7007600000000000000",
        #                 "first_fill_timestamp": "1679728133",
        #                 "last_fill_timestamp": "1679728133"
        #             }
        #         ]
        #     }
        #
        closedOrders = []
        orders = self.safe_list(response, 'orders', [])
        for i in range(0, len(orders)):
            order = orders[i]
            if self.is_archive_order_closed(order):
                closedOrders.append(self.extend({'status': 'closed'}, order))
        return self.parse_orders(closedOrders, market, since, limit)

