    def fetch_funding_history(self, symbol: Str = None, since: Int = None, limit: Int = None, params={}) -> List[FundingHistory]:
        """
        fetch the history of funding payments paid and received on self account

        https://docs.nado.xyz/developer-resources/api/archive-indexer/interest-and-funding-payments

        :param str symbol: unified market symbol
        :param int [since]: the earliest time in ms to fetch funding history for
        :param int [limit]: the maximum number of funding history structures to retrieve
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.subaccount]: the 12-byte subaccount identifier, defaults to 'default'
        :returns dict[]: a list of `funding history structures <https://docs.ccxt.com/?id=funding-history-structure>`
        """
        if symbol is None:
            raise ArgumentsRequired(self.id + ' fetchFundingHistory() requires a symbol argument')
        if self.walletAddress is None:
            raise ArgumentsRequired(self.id + ' fetchFundingHistory() requires walletAddress')
        self.load_markets()
        market = self.market(symbol)
        if not market['swap']:
            raise BadSymbol(self.id + ' fetchFundingHistory() supports swap contracts only')
        subaccount = None
        subaccount, params = self.handle_option_and_params(params, 'fetchFundingHistory', 'subaccount', 'default')
        request = {
            'interest_and_funding': {
                'subaccount': self.create_subaccount(self.walletAddress, subaccount),
                'product_ids': [
                    self.parse_to_int(market['id']),
                ],
                'limit': 100 if (limit is None) else min(limit, 100),
            },
        }
        response = self.archivePost(self.deep_extend(request, params))
        #
        #     {
        #         "interest_payments": [],
        #         "funding_payments": [
        #             {
        #                 "product_id": 2,
        #                 "idx": "5968022",
        #                 "timestamp": "1701698400",
        #                 "amount": "-12273223338657163",
        #                 "balance_amount": "1000000000000000000",
        #                 "rate_x18": "47928279191008320",
        #                 "oracle_price_x18": "2243215034242228224820"
        #             }
        #         ],
        #         "next_idx": "1314805"
        #     }
        #
        fundingPayments = self.safe_list(response, 'funding_payments', [])
        result = []
        for i in range(0, len(fundingPayments)):
            result.append(self.parse_funding_history(fundingPayments[i], market))
        sorted = self.sort_by(result, 'timestamp')
        return self.filter_by_symbol_since_limit(sorted, symbol, since, limit)

    def fetch_funding_rates(self, symbols: Strings = None, params={}) -> FundingRates:
        """
        fetch the funding rate for multiple markets

        https://docs.nado.xyz/developer-resources/api/v2/contracts

        :param str[] [symbols]: list of unified market symbols
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param boolean [params.edge]: whether to retrieve volume and open interest metrics for all chains, defaults to True
        :returns dict: a dictionary of `funding rate structures <https://docs.ccxt.com/?id=funding-rates-structure>`, indexed by market symbols
        """
        self.load_markets()
        symbols = self.market_symbols(symbols, 'swap', True)
        response = self.archiveV2PublicGetContracts(params)
        #
        #     {
        #         "BTC-PERP_USDT0": {
        #             "product_id": 1,
        #             "ticker_id": "BTC-PERP_USDT0",
        #             "base_currency": "BTC-PERP",
        #             "quote_currency": "USDT0",
        #             "last_price": 25744.0,
        #             "base_volume": 794.154,
        #             "quote_volume": 20475749.367766097,
        #             "product_type": "perpetual",
        #             "contract_price": 25830.738843799172,
        #             "contract_price_currency": "USD",
        #             "open_interest": 3059.325,
        #             "open_interest_usd": 79024625.11330591,
        #             "index_price": 25878.913320746455,
        #             "mark_price": 25783.996946729356,
