    def fetch_open_interests(self, symbols: Strings = None, params={}):
        """
        retrieves the open interests of some currencies

        https://docs.nado.xyz/developer-resources/api/v2/contracts

        :param str[] [symbols]: unified CCXT market symbols
        :param dict [params]: exchange specific parameters
        :param boolean [params.edge]: whether to retrieve volume and open interest metrics for all chains, defaults to True
        :returns dict: a dictionary of `open interest structures <https://docs.ccxt.com/?id=open-interest-structure>`
        """
        self.load_markets()
        symbols = self.market_symbols(symbols, 'swap', True)
        response = self.archiveV2PublicGetContracts(params)
        #
        #     {
        #         "BTC-PERP_USDT0": {
        #             "product_id": 1,
        #             "ticker_id": "BTC-PERP_USDT0",
        #             "base_currency": "BTC-PERP",
        #             "quote_currency": "USDT0",
        #             "last_price": 25744.0,
        #             "base_volume": 794.154,
        #             "quote_volume": 20475749.367766097,
        #             "product_type": "perpetual",
        #             "contract_price": 25830.738843799172,
        #             "contract_price_currency": "USD",
        #             "open_interest": 3059.325,
        #             "open_interest_usd": 79024625.11330591,
        #             "index_price": 25878.913320746455,
        #             "mark_price": 25783.996946729356,
        #             "funding_rate": -0.003664562348812546,
        #             "next_funding_rate_timestamp": 1694379600,
        #             "price_change_percent_24h": -0.6348599635253989
        #         }
        #     }
        #
        tickers = list(response.keys())
        interests = []
        for i in range(0, len(tickers)):
            ticker = tickers[i]
            interests.append(response[ticker])
        return self.parse_open_interests(interests, symbols)

    def fetch_order_book(self, symbol: str, limit: Int = None, params={}) -> OrderBook:
        """
        fetches information on open orders with bid(buy) and ask(sell) prices, volumes and other data

        https://docs.nado.xyz/developer-resources/api/v2/orderbook

        :param str symbol: unified symbol of the market to fetch the order book for
        :param int [limit]: the maximum amount of order book entries to return
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: A dictionary of `order book structures <https://docs.ccxt.com/?id=order-book-structure>`
        """
        self.load_markets()
        market = self.market(symbol)
        tickerId = self.safe_string(market['info'], 'ticker_id')
        request = {
            'ticker_id': tickerId,
            'depth': 100 if (limit is None) else limit,
        }
        response = self.gatewayV2PublicGetOrderbook(self.extend(request, params))
        #
        #     {
        #         "product_id": 1,
        #         "ticker_id": "BTC-PERP_USDT0",
        #         "bids": [
        #             [116215.0, 0.128],
        #             [116214.0, 0.172]
        #         ],
        #         "asks": [
        #             [116225.0, 0.043],
        #             [116226.0, 0.172]
        #         ],
        #         "timestamp": 1757913317944
        #     }
        #
        timestamp = self.safe_integer(response, 'timestamp')
        return self.parse_order_book(response, market['symbol'], timestamp)

    def fetch_trades(self, symbol: str, since: Int = None, limit: Int = None, params={}) -> List[Trade]:
        """
        get the list of the most recent trades for a particular symbol

        https://docs.nado.xyz/developer-resources/api/v2/trades

        :param str symbol: unified symbol of the market to fetch trades for
        :param int [since]: timestamp in ms of the earliest trade to fetch
        :param int [limit]: the maximum amount of trades to fetch
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param int [params.max_trade_id]: max trade id to include in the result for pagination
        :returns Trade[]: a list of `trade structures <https://docs.ccxt.com/?id=public-trades>`
        """
        self.load_markets()
        market = self.market(symbol)
        tickerId = self.safe_string(market['info'], 'ticker_id')
        request = {
            'ticker_id': tickerId,
        }
        if limit is not None:
            request['limit'] = min(limit, 500)
        response = self.archiveV2PublicGetTrades(self.extend(request, params))
        #
        #     [
        #         {
        #             "product_id": 1,
        #             "ticker_id": "BTC-PERP_USDT0",
        #             "trade_id": 6351,
        #             "price": 112029.5896,
        #             "base_filled": -0.388,
        #             "quote_filled": 43467.4807648,
        #             "timestamp": 1757335618,
        #             "trade_type": "sell"
        #         }
        #     ]
        #
        return self.parse_trades(response, market, since, limit)

    def fetch_ohlcv(self, symbol: str, timeframe: str = '1m', since: Int = None, limit: Int = None, params={}) -> List[list]:
        """
        fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market

        https://docs.nado.xyz/developer-resources/api/archive-indexer/candlesticks

        :param str symbol: unified symbol of the market to fetch OHLCV data for
        :param str timeframe: the length of time each candle represents
        :param int [since]: timestamp in ms of the earliest candle to fetch
        :param int [limit]: the maximum amount of candles to fetch
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param int [params.until]: timestamp in ms of the latest candle to fetch
        :returns int[][]: A list of candles ordered, open, high, low, close, volume
        """
        self.load_markets()
        market = self.market(symbol)
        until = self.safe_integer(params, 'until')
        params = self.omit(params, 'until')
        request = {
            'candlesticks': {
                'product_id': self.parse_to_int(market['id']),
                'granularity': self.safe_integer(self.timeframes, timeframe, self.parse_timeframe(timeframe)),
            },
        }
        if limit is not None:
            request['candlesticks']['limit'] = limit
        if until is not None:
            request['candlesticks']['max_time'] = self.parse_to_int(until / 1000)
        response = self.archivePost(self.deep_extend(request, params))
        #
        #     {
        #         "candlesticks": [
        #             {
        #                 "product_id": 1,
        #                 "granularity": 60,
        #                 "submission_idx": "627709",
        #                 "timestamp": "1680118140",
        #                 "open_x18": "27235000000000000000000",
        #                 "high_x18": "27298000000000000000000",
        #                 "low_x18": "27235000000000000000000",
        #                 "close_x18": "27298000000000000000000",
        #                 "volume": "1999999999999999998"
        #             }
        #         ]
        #     }
        #
        data = self.safe_list(response, 'candlesticks', [])
        return self.parse_ohlcvs(data, market, timeframe, since, limit)

    def parse_ohlcv(self, ohlcv, market: Market = None) -> list:
        #
        #     {
        #         "product_id": 1,
        #         "granularity": 60,
        #         "submission_idx": "627709",
        #         "timestamp": "1680118140",
        #         "open_x18": "27235000000000000000000",
        #         "high_x18": "27298000000000000000000",
        #         "low_x18": "27235000000000000000000",
        #         "close_x18": "27298000000000000000000",
        #         "volume": "1999999999999999998"
        #     }
        #
        return [
            self.safe_timestamp(ohlcv, 'timestamp'),
            self.parse_x18(self.safe_string(ohlcv, 'open_x18')),
            self.parse_x18(self.safe_string(ohlcv, 'high_x18')),
            self.parse_x18(self.safe_string(ohlcv, 'low_x18')),
            self.parse_x18(self.safe_string(ohlcv, 'close_x18')),
            self.parse_x18(self.safe_string(ohlcv, 'volume')),
        ]

    def parse_trade(self, trade: dict, market: Market = None) -> Trade:
        #
        #     {
        #         "product_id": 1,
        #         "ticker_id": "BTC-PERP_USDT0",
        #         "trade_id": 6351,
        #         "price": 112029.5896,
        #         "base_filled": -0.388,
        #         "quote_filled": 43467.4807648,
        #         "timestamp": 1757335618,
        #         "trade_type": "sell"
        #     }
        #
        # archive match
        #
        #     {
        #         "submission_idx": "563012",
        #         "product_id": 2,
        #         "timestamp": "1679728133",
        #         "digest": "0x80ce789702b670b7d33f2aa67e12c85f124395c3f9acdb422dde3b4973ccd50c",
        #         "order": {
        #             "priceX18": "27544000000000000000000",
        #             "amount": "2000000000000000000"
        #         },
        #         "base_filled": "736000000000000000",
        #         "quote_filled": "-20276464287857571514302",
        #         "fee": "4055287857571514302",
        #         "is_taker": True
        #     }
        #
        marketId = self.safe_string(trade, 'product_id')
        market = self.safe_market(marketId, market)
        timestamp = self.safe_timestamp(trade, 'timestamp')
        rawOrder = self.safe_dict(trade, 'order')
        isArchiveMatch = rawOrder is not None
        order = {} if (rawOrder is None) else rawOrder
        amountString = self.safe_string(trade, 'base_filled')
        costString = self.safe_string(trade, 'quote_filled')
        rawOrderAmount = self.safe_string(order, 'amount')
        side = self.safe_string(trade, 'trade_type')
        if (side is None) and (rawOrderAmount is not None):
            if Precise.string_lt(rawOrderAmount, '0'):
                side = 'sell'
            else:
                side = 'buy'
        price = self.safe_string(trade, 'price')
        if price is None:
            parsedPrice = self.parse_x18(self.safe_string(order, 'priceX18'))
            price = None if (parsedPrice is None) else self.number_to_string(parsedPrice)
        takerOrMaker = None
        isTaker = self.safe_bool(trade, 'is_taker')
        if isTaker is not None:
            if isTaker:
                takerOrMaker = 'taker'
            else:
                takerOrMaker = 'maker'
        feeString = self.safe_string(trade, 'fee')
        feeCost = None
        if isArchiveMatch:
            feeCost = self.parse_x18(feeString)
        else:
            feeCost = self.parse_number(feeString)
        fee = None
        if feeCost is not None:
            fee = {
                'cost': feeCost,
                'currency': market['quote'],
            }
        parsedAmount = None
        if amountString is not None:
            absoluteAmount = Precise.string_abs(amountString)
            if isArchiveMatch:
                parsedAmount = self.parse_x18(absoluteAmount)
            else:
                parsedAmount = absoluteAmount
        parsedCost = None
        if costString is not None:
            absoluteCost = Precise.string_abs(costString)
            if isArchiveMatch:
                parsedCost = self.parse_x18(absoluteCost)
            else:
                parsedCost = absoluteCost
        return self.safe_trade({
            'info': trade,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'symbol': market['symbol'],
            'id': self.safe_string_2(trade, 'trade_id', 'submission_idx'),
            'order': self.safe_string(trade, 'digest'),
            'type': None,
            'side': side,
            'takerOrMaker': takerOrMaker,
            'price': price,
            'amount': parsedAmount,
            'cost': parsedCost,
            'fee': fee,
        }, market)

