    def sign_fetch_trigger_orders(self, tx, chainId, endpointAddress):
        domain = {
            'name': 'Nado',
            'version': '0.0.1',
            'chainId': chainId,
            'verifyingContract': endpointAddress,
        }
        messageTypes = {
            'ListTriggerOrders': [
                {'name': 'sender', 'type': 'bytes32'},
                {'name': 'recvTime', 'type': 'uint64'},
            ],
        }
        encoded = self.eth_encode_structured_data(domain, messageTypes, tx)
        hash = '0x' + self.hash(encoded, 'keccak', 'hex')
        return self.sign_hash(hash, self.privateKey)

    def sign_hash(self, hash, privateKey):
        signature = self.ecdsa(hash[-64:], privateKey[-64:], 'secp256k1', None)
        r = signature['r']
        s = signature['s']
        v = self.int_to_base16(self.sum(27, signature['v'])).lower()
        return '0x' + self.pad_hex(r, 64) + self.pad_hex(s, 64) + v

    def remove_market_suffix(self, marketId):
        if marketId is None:
            return None
        if marketId.endswith('-PERP'):
            return marketId[0:-5]
        return marketId

    def sign(self, path, api=[], method='GET', params={}, headers=None, body=None):
        endpoint = api[0]
        if isinstance(api, str):
            endpoint = api
        url = self.urls['api'][endpoint]
        if path != '':
            url += '/' + self.implode_params(path, params)
        query = self.omit(params, self.extract_params(path))
        headers = {}
        if (endpoint == 'gateway') or (endpoint == 'archive'):
            headers['Accept-Encoding'] = 'gzip, br, deflate'
        if method == 'GET':
            if query:
                url += '?' + self.urlencode(query)
        else:
            headers['Content-Type'] = 'application/json'
            body = self.json(query)
        return {'url': url, 'method': method, 'body': body, 'headers': headers}

    def handle_errors(self, httpCode: Int, reason: str, url: str, method: str, headers: dict, body: str, response, requestHeaders, requestBody):
        if not response:
            return None  # fallback to default error handler
        #
        #     {
        #         "status": "failure",
        #         "signature": "0x...",
        #         "error_code": 2007,
        #         "error": "Order price must be within a range of 80% to 120% of oracle price.",
        #         "request_type": "execute_place_order"
        #     }
        #
        status = self.safe_string(response, 'status')
        errorCode = self.safe_string(response, 'error_code')
        error = self.safe_string(response, 'error')
        if (status == 'failure') or (errorCode is not None) or (error is not None):
            feedback = self.id + ' ' + body
            self.throw_exactly_matched_exception(self.exceptions['exact'], errorCode, feedback)
            self.throw_broadly_matched_exception(self.exceptions['broad'], error, feedback)
            raise ExchangeError(feedback)  # unknown message
        return None
